from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    line = max((v for v in counts if v != bg), key=lambda v: counts[v])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for a, b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == bg and (a,b) not in seen:
                        seen.add((a,b))
                        q.append((a,b))
            comps.append(cells)
    out = [row[:] for row in grid]
    largest = max(map(len, comps))
    for cells in comps:
        r0 = min(r for r,c in cells); r1 = max(r for r,c in cells)
        c0 = min(c for r,c in cells); c1 = max(c for r,c in cells)
        rectangular = len(cells) == (r1-r0+1)*(c1-c0+1)
        edges = set()
        for r,c in cells:
            if r == 0: edges.add('top')
            if r == h-1: edges.add('bottom')
            if c == 0: edges.add('left')
            if c == w-1: edges.add('right')
        # Fill enclosed rectangular rooms, including rooms against a single
        # canvas edge, while leaving corner-connected exterior regions alone.
        if rectangular and len(cells) < largest and len(edges) <= 1:
            for r,c in cells:
                out[r][c] = 4
    return out
